        self.x = int(input());

    def lam(self) -> None:
        tong = 0;
        x = abs(self.x);
        while(tong < x or (tong - x) % 2 != 0):
            self.dem += 1;
            tong += self.dem;

    def ra(self) -> None:
        print(self.dem);


def main():
